"""Fresh final-recon episode with reproduced bilevel settings, with checkpoint media."""
from pathlib import Path
import argparse,json,os,subprocess,sys,hashlib
B=Path(__file__).resolve().parents[1]
def main():
 p=argparse.ArgumentParser();p.add_argument('--phase',choices=['smoke','pilot'],default='smoke');p.add_argument('--seed',type=int,default=42);p.add_argument('--worlds',type=int,default=2048);p.add_argument('--dry-run',action='store_true');a=p.parse_args()
 f=B/'frozen/episode_000037';manifest=json.loads((B/'frozen_manifest.json').read_text())[0]
 for rel,h in {'reference.parquet':manifest['runtime_sha256'],**manifest['asset_sha256']}.items():
  assert hashlib.sha256((f/rel).read_bytes()).hexdigest()==h,rel
 run=B/'runs'/a.phase/'episode_000037/chunk'/f'seed_{a.seed}';train=run/'training';train.mkdir(parents=True,exist_ok=True)
 if list(train.glob('policy_*.safetensors')) or (train/'upper_updates.jsonl').exists():raise RuntimeError('Fresh runs only; complete bilevel resume is not implemented')
 total=131072 if a.phase=='smoke' else 50331648;interval=65536 if a.phase=='smoke' else 2508800
 search_interval=32768 if a.phase=='smoke' else 2508800
 cmd=['scripts/train_flash_sac.py','curriculum=tracking_lower_only','embodiment=sharpa_hands_stronger','action.wrist_kp=100.0','action.wrist_tau_max=90.0',f'task.parquet={f/"reference.parquet"}','task.motion_speed=1.0',f'task.robot_reference_path={B}/priors/d3_lateral_tripod_sq03.npz','task.robot_reference_sha256=ffc3e1bd362987aeec8d6cc8316d1ea14107dd77b359b3a897b92d8de20dbbcb','+bilevel.grasp_max_squeeze=0.5',f'reset.seed={a.seed}',f'training.seed={a.seed}',f'scene.world_count={a.worlds}','scene.support=true','collision.ground=false','sim.njmax=2048','sim.nconmax=512','sim.substeps=20',f'training.total_environment_steps={total}','training.updates_per_collection=8','training.replay.capacity=1048576',f'training.replay.minimum_size={32768 if a.phase=="smoke" else 102400}','training.replay.batch_size=1024',f'training.checkpoint.save_interval_environment_steps={interval}','+adaptive_voc.mode=step_schedule',f'+adaptive_voc.interval={32768 if a.phase=="smoke" else 2097152}','+adaptive_voc.required_passes=3','+adaptive_voc.scales=[1.0,0.75,0.5,0.25,0.1,0.05,0.025,0.01,0.0]','env.voc_scale=1.0','reset.voc_decay_steps=0','+bilevel.engine=parallel_flashsac','+bilevel.edit_scope=wrists_and_eigen_fingers','+bilevel.replicas=16','+bilevel.train_on_proposals=true','+bilevel.proposal_fraction=0.5','+bilevel.baseline_replicas=128',f'+bilevel.finger_eigen_basis_path={B}/priors/grasp_eigen_basis.npz',f'+training.network.eigen_basis_path={B}/priors/sharpa_bimanual_residual_basis.npz',f'+training.network.eigen_basis_sha256={hashlib.sha256((B/"priors/sharpa_bimanual_residual_basis.npz").read_bytes()).hexdigest()}','+bilevel.mode=reactor_wrench','+bilevel.study_variant=chunk','+bilevel.chunk_seconds=1.0',f'+bilevel.warmup={search_interval}',f'+bilevel.interval={search_interval}',f'+bilevel.eval_worlds={a.worlds}',f'+bilevel.upper_trials={a.worlds}','+bilevel.contact_proximity_weight=5.0','+bilevel.select_best_trial=true','+bilevel.ilc_candidates=true','+bilevel.hold_refine_rounds=12','+bilevel.hold_position_m=0.04','+bilevel.failure_window=true','+bilevel.window_detect=motion','+bilevel.stop_success_fraction=0.9','+bilevel.ilc_specs=["0.75:xy:0:0","1.0:xy:0:0","1.25:xy:0:0","1.0:xyz:0:0","1.0:xy:0.5:0","0.5:xy:0.5:0","0:xy:0.5:0"]','+reference_guided_hands=true','objective.hand_keypoints.weight=2.0','objective.hand_joint_pos.weight=1.0','objective.contact_wrench_support.weight=0.0','objective.missed_contact.weight=0.0','objective.unintended_contact.weight=0.0','termination.object_position.enabled=false','termination.object_orientation.enabled=false','action.wrist_pos_clip=0.03','action.wrist_ori_clip=0.2','action.finger_joint_pos_clip=0.3','+objective.hand_keypoint_palm_weight=10.0','+bilevel.wrist_translation_offset_m=0.08','+bilevel.wrist_translation_correction_speed_m_s=0.25','+bilevel.wrist_rotation_offset_rad=0.7','training.mixed_precision=false','training.compute_dtype=float32','logging.mode=disabled',f'output_dir={train}',f'hydra.run.dir={train/"hydra"}']
 config={'phase':a.phase,'episode':manifest,'variant':'chunk','seed':a.seed,'voc_mode':'step_schedule','voc_initial_scale':1.0,'voc_scales':[1.,.75,.5,.25,.1,.05,.025,.01,0.],'voc_probe_interval':32768 if a.phase=='smoke' else 2097152,'voc_required_passes':3,'voc_reduction_rule':'both objects pass next-lower-scale full-horizon evaluation three consecutive checks','total_environment_steps':total,'upper_trials':a.worlds,'eval_worlds':a.worlds,'replicas_per_candidate':1,'worlds':a.worlds,'checkpoint_interval':interval,'upper_search_interval':search_interval,'upper_search_warmup':search_interval,'planned_upper_search_rounds':(total-1)//search_interval,'training_command':cmd,'code_root':str(B/'flash_chord'),'contact_proximity':True,'reference_guided':True,'wrist_translation_bound_m':.08,'wrist_rotation_bound_rad':.7,'hand_keypoint_reward_weight':2.0,'finger_joint_tracking_reward_weight':1.0,'lower_reward':'tracking only: hand keypoints, finger joints, wrist-deviation termination, action regularizers','lower_residual_clip':{'wrist_pos_m':.03,'wrist_ori_rad':.2,'finger_rad':.3},'object_termination':False,'keypoint_palm_relative_weight':10.0,'upper_edit_scope':'wrists_and_eigen_fingers','upper_action_dimension':22*((manifest['frames']-3)//max(1,round(manifest['fps']))+1),'lower_action_dimension':56,'finger_exploration':'official Sharpa PCA, rank 9 per hand; learned diagonal plus low-rank tanh Gaussian','eigen_basis_sha256':hashlib.sha256((B/'priors/sharpa_bimanual_residual_basis.npz').read_bytes()).hexdigest(),'initial_finger_variance_fraction_eigen':0.5,'original_overlay_opacity':0.45,'overlay_style':'transparent original hands plus synchronized hand-object closeups','wrist_control':{'kp':100.0,'kd':12.0,'effort_limit':90.0},'media_mode':'synchronous at every checkpoint using the same GPU allocation; training paused during renders','contact_labels':'provided final_recon geometric estimates; immutable during training','support_table':json.loads((B/'reproduction/support_table.json').read_text()),'physics_corrections':['80cm gravity-horizontal table at frame-0 collision base; ground plane disabled','full-inertia-tensor VOC torque'],'launch_attempt':1,'recipe':'tracklower-repaired-000037-dexinit-ilcauto3-20261018-ilcauto3','upper_physics_feedback':'in-loop ILC v2 (wrist translation, rotation about object, slip squeeze), stable-world statistics, same replica gate','checkpoint_every_upper_round':True,'failure_window':'[min(contact onset, miss start)-0.25 s, detection], 3 cm / 30 deg','hold_refine':'freeze lower after an accepted round holding <= 0.04 m, 12 upper rounds','stop_on_success':'run ends after an accepted round with replica success fraction >= 0.9 and unstable <= 0.1; pair in training/success_pair.json','initial_reference':'Dexonomy grasp fit d3_lateral_tripod_sq03 (priors/dexfit.json)','grasp_prior':'grasp eigenspace: PCA of Dexonomy 33 + human 8 postures (ep1 held out), rank 8/hand, 94.4% var','lower_training_references':'50% current reference + 50% this round candidate references (train on proposals)','two_timescale':'upper every 2.5M steps; replay cleared only on accepted reference changes','upper_evaluation':'120 candidates x 16 replicas + 128 baseline replicas; accept iff mean improves by >2 SE','object_centric_grasps':'priors/object_centric_grasps.npz','grasp_max_squeeze_rad':0.5,'scene':'DexAgent-repaired final_recon ep1: repaired collision meshes, measured table+gravity (9.17 deg), seated frame-0 objects; targets unchanged','grasp_prior':{'library':'priors/grasp_library.npz','sources':'Dexonomy 33 GRASP types (Shadow->Sharpa) + 8 human-video clusters','held_out_episode':'episode_000037'}}
 (run/'run_config.json').write_text(json.dumps(config,indent=2)+'\n')
 if a.dry_run:print(json.dumps(config,indent=2));return
 def stage(s,**kw):(run/'stage.json').write_text(json.dumps({'stage':s,**kw},indent=2)+'\n')
 env=os.environ.copy();env['V2D_CHECK_FINITE']='1';env['UNIRETARGET_CHECKPOINT_MEDIA']=str(B/'code/checkpoint_media.py');env['UNIRETARGET_PHASE']=a.phase;env['UNIRETARGET_SEED']=str(a.seed)
 try:
  stage('training');subprocess.run([sys.executable,*cmd],cwd='/workspace',env=env,check=True)
  checkpoints=sorted(train.glob('policy_*.safetensors'),key=lambda p:int(p.stem.split('_')[-1]));assert checkpoints
  stage('unassisted_evaluation');out=run/'evaluation';out.mkdir(exist_ok=True)
  subprocess.run([sys.executable,'scripts/evaluate_policy.py',f'evaluation.checkpoint={checkpoints[-1]}','evaluation.world_count=1','evaluation.reset_mode=explicit',f'evaluation.metrics_output={out/"metrics.json"}',f'hydra.run.dir={out/"hydra"}','logging.mode=disabled'],cwd='/workspace',check=True)
  assert not (train/'nonfinite_transition.json').exists()
  updates=[json.loads(line) for line in (train/'upper_updates.jsonl').read_text().splitlines()]
  assert updates, 'Upper search never executed'
  media=list(run.glob('checkpoint_videos/step_*/manifest.json'));assert len(media)==len(checkpoints),'Missing evaluation videos'
  assert len(list(run.glob('voc_checkpoint_videos/step_*/manifest.json')))==len(checkpoints),'Missing current-VOC videos'
  assert list(run.glob('reference_overlays/version_*/transparent_closeups/complete.json')),'Missing reference overlay'
  stage('complete')
 except Exception as e:stage('failed',error=str(e));raise
 finally:
  subprocess.run([sys.executable,str(B/'code/wandb_sync.py'),a.phase,'episode_000037','chunk',str(a.seed),'--once'],cwd='/workspace')
if __name__=='__main__':main()
